def nv12(bits):
    image=bytearray(b'\xff'*(640*480)+b'\x80'*(640*240))
    width=len(bits)*6;left=(640-width)//2;top=(480-width)//2
    for y,row in enumerate(bits):
        line=b''.join(bytes([0 if bit=='1' else 255])*6 for bit in row)
        for j in range(6):
            p=(top+y*6+j)*640+left;image[p:p+width]=line
    return image
frames=[nv12(bits) for bits in rows]
class Pixels:
    active=False;starts=0;stops=0;count=0
    def start_video_stream_mode(self):assert not self.active;self.active=True;self.starts+=1
    def read_video_stream(self):
        assert self.active
        value=frames[self.count];self.count+=1;return value
    def stop_video_stream_mode(self):
        if self.active:self.active=False;self.stops+=1
class RecordingPreview(CooperativePreview):
    def __init__(self):super().__init__();self.states=[];self.hashes=[]
    def set_value(self,status):
        super().set_value(status)
        for _ in range(25):ui.tick();time.sleep_ms(5)
        self.states.append(ui.scan_state());self.hashes.append(hashlib.sha256(ui.framebuffer()).hexdigest())
        if len(self.states)==1:
            picture=ui.framebuffer()
            print('@@UI_RGB565_BEGIN 240 240')
            for y in range(240):print('@@UI_ROW',bytes(picture[y*480:(y+1)*480]).hex())
            print('@@UI_RGB565_END')
