# Real native surface must close through Python exceptions before control returns.
class Broken(Pixels):
    def read_video_stream(self):raise RuntimeError('PUBLIC deliberate source error')
for interrupt in (False,True):
    source=Broken();preview=CooperativePreview()
    if interrupt:
        class Interrupted(Broken):
            def read_video_stream(self):raise KeyboardInterrupt()
        source=Interrupted()
    screen=NativeScanScreen(decoder=DecodeQR(),camera=source,preview=preview,buttons=ButtonInput(read_mask=lambda:0),instructions_text='Scan a QR code')
    try:screen.run();assert False
    except KeyboardInterrupt:assert interrupt
    except RuntimeError:assert not interrupt
    assert not ui.scan_state()['active'] and not preview.active and source.stops==1
assert machine.last_reset() is None
